@Scheduled(fixedDelay = 10_000)
void sendReminders() {
    String token = UUID.randomUUID().toString();     // mỗi lần lấy lock một token riêng
    Boolean acquired = redis.opsForValue().setIfAbsent(LOCK_KEY, token, Duration.ofSeconds(60));
    if (!Boolean.TRUE.equals(acquired)) {
        return;
    }
    try {
        for (Reminder reminder : reminderRepository.findPending(200)) {   // lô nhỏ, chạy xong trong TTL
            // Lock chỉ để giảm việc trùng. Chặn trùng thật là lần ghi có điều kiện này.
            int claimed = jdbc.update("""
                    update reminders set status = 'SENDING', claimed_at = now()
                    where id = ? and status = 'PENDING'""", reminder.id());
            if (claimed == 0) {
                continue;                                          // pod khác đã nhận hoá đơn này
            }
            mailClient.send(reminder.toEmail(), "reminder-" + reminder.id()); // idempotency key cho nhà cung cấp
            reminderRepository.markSent(reminder.id());
        }
    } finally {
        redis.execute(RELEASE_SCRIPT, List.of(LOCK_KEY), token);  // chỉ xoá nếu vẫn là lock của mình
    }
}

private static final RedisScript<Long> RELEASE_SCRIPT = RedisScript.of("""
        if redis.call('get', KEYS[1]) == ARGV[1] then
            return redis.call('del', KEYS[1])
        end
        return 0""", Long.class);
